/* eslint-disable react/require-default-props */
import React, { HTMLProps } from 'react';
import { IconProps, Link } from '@hexa-ui/icons';
import type * as Stitches from '@stitches/react';
import { config } from '@hexa-ui/theme';
import { StyledButton } from './TextButton.styles';

type CSSVariants = Stitches.CSS<typeof config>;

export interface TextButtonTypes extends Omit<HTMLProps<HTMLButtonElement>, 'size' | 'type'> {
  size?: 'large' | 'medium' | 'small';
  iconPosition?: 'trailing' | 'leading';
  icon?: React.FunctionComponent<IconProps>;
  css?: CSSVariants;
  type?: 'button' | 'reset' | 'submit';
}

export const TextButton = React.forwardRef(
  (
    {
      size = 'medium',
      iconPosition,
      icon: Icon = Link,
      children,
      css,
      ...props
    }: Omit<TextButtonTypes, 'as'>,
    forwardedRef: React.ForwardedRef<HTMLButtonElement>
  ): JSX.Element => (
    <StyledButton size={size} css={css} {...props} ref={forwardedRef} type={props.type}>
      {iconPosition === 'leading' && <Icon size="medium" style={{ marginRight: '0.5rem' }} />}
      {children}
      {iconPosition === 'trailing' && <Icon size="medium" style={{ marginLeft: '0.25rem' }} />}
    </StyledButton>
  )
);
